function generateG3ColumnTask(topicId,stageIndex){
 const raw=rawCourseId(topicId),d=Math.max(0,Math.min(2,Number(stageIndex)||0));
 if(raw==="written_add"){
  let a=0,b=0,ans=0,carries=0,guard=0;do{guard++;a=ri(d===0?20:100,d===0?599:899);b=ri(d===0?10:40,d===0?399:899);ans=a+b;if(ans>1000)continue;carries=g3HasCarry(a,b)}while(((d===0&&carries!==0)||(d===1&&(carries<1||carries>1))||(d===2&&carries<2)||ans>1000)&&guard<800);
  if(ans>1000||(d===0&&carries)||(d===1&&carries!==1)||(d===2&&carries<2)){[a,b]=d===0?[243,315]:d===1?[268,125]:[487,356];ans=a+b}
  const cols=Math.max(String(a).length,String(b).length,String(ans).length);return {a,b,ans,op:"+",marks:calcCarries(a,b,cols),g3Topic:raw,audit:{type:"g3WrittenAdd",a,b,answer:ans,carries:g3HasCarry(a,b)}};
 }
 if(raw==="written_subtract"){
  let a=0,b=0,ans=0,borrows=0,guard=0;if(d===2&&Math.random()<.55){const pool=[[500,247],[600,358],[702,368],[800,456],[905,478],[700,286]];[a,b]=g6RandomFrom(pool)}else do{guard++;a=ri(d===0?200:300,999);b=ri(20,a-1);borrows=g3BorrowCount(a,b)}while(((d===0&&borrows!==0)||(d===1&&borrows<1)||(d===2&&borrows<2))&&guard<900);ans=a-b;if(!a||ans<0){[a,b]=d===0?[786,243]:d===1?[452,178]:[702,368];ans=a-b}const cols=Math.max(String(a).length,String(b).length,String(ans).length),bm=calcBorrows(a,b,cols);return {a,b,ans,op:"−",marks:bm.receive,dotMarks:bm.donor,g3Topic:raw,audit:{type:"g3WrittenSub",a,b,answer:ans,borrows:g3BorrowCount(a,b),throughZero:g3BorrowThroughZero(a,b)}};
 }
 if(raw==="written_multiply"){
  let a=0,b=0,ans=0,guard=0,carry=0;do{guard++;a=ri(d===0?11:20,d===0?33:d===1?39:49);b=ri(d===0?2:2,d===0?3:d===1?5:9);ans=a*b;carry=Math.floor((a%10)*b/10)}while(((d===0&&carry>0)||(d===1&&carry===0)||(ans>200))&&guard<600);if(!a||ans>250){a=d===0?23:d===1?27:38;b=d===0?3:d===1?3:2;ans=a*b}const cols=Math.max(String(a).length,String(ans).length);return {a,b,ans,op:"×",units:b,tens:0,cols,carry1:calcMulCarries(a,b,cols),singleDigitMultiplier:true,g3Topic:raw,audit:{type:"g3WrittenMul",a,b,answer:ans,carry:Math.floor((a%10)*b/10)>0}};
 }
 if(raw==="written_divide"){
  const divisor=ri(2,d===0?5:9),qMin=d===0?11:12,qMax=d===0?24:d===1?49:99;let q=ri(qMin,qMax),dividend=q*divisor,guard=0;while((dividend>999||dividend<20)&&guard++<100){q=ri(qMin,qMax);dividend=q*divisor}const steps=divisionSteps(dividend,divisor);return {a:dividend,b:divisor,ans:q,op:"÷",steps,quotient:steps.map(x=>x.qd).join(""),g3Topic:raw,audit:{type:"g3WrittenDiv",dividend,divisor,quotient:q,remainder:dividend%divisor}};
 }
 return null;
}

