function openGrade(grade){
 const requested=Number(grade);
 if(![3,4,5,6,7,8].includes(requested))return renderHome();
 currentGrade=requested;
 const back=document.getElementById("gradeBackPill");if(back)back.style.display="";
 if(brandLogo)brandLogo.textContent=String(grade);
 if(brandTitle)brandTitle.textContent=`МатКвест — ${grade} класс`;
 if(currentGrade===3)renderGrade3();else if(currentGrade===4)renderGrade4();else if(currentGrade===5)renderGrade5();else if(currentGrade===6)renderGrade6();else if(currentGrade===7)renderGrade7();else renderGrade8();
}

