function makeQ(id){
 const d=activeDifficulty();
 let text,ans,vals=[],ex,sig,variant;

 if(id==="numbers"){
   const variants=d===0?["compare","round100","place"]:d===1?["compare","round1000","expanded","difference"]:["compare","round10000","expanded","difference","place"];
   variant=variants[ri(0,variants.length-1)];
   const lo=d===0?1000:d===1?10000:100000,hi=d===0?9999:d===1?99999:999999;
   if(variant==="compare"){
     const a=ri(lo,hi),b=a+ri(10,d===0?500:d===1?3000:9000);text=`Какое число больше: <b>${a}</b> или <b>${b}</b>?`;ans=b;vals=[a,b+10,Math.max(0,a-10)];ex=`Сравниваем со старших разрядов. Больше число ${b}.`;sig=`numbers:${d}:compare:${a}:${b}`;
   }else if(variant==="round100"){
     const a=ri(lo,hi);ans=Math.round(a/100)*100;text=`Округли число <b>${a}</b> до сотен.`;vals=[ans+100,Math.max(0,ans-100),Math.round(a/10)*10];ex=`Смотрим на десятки. Получаем ${ans}.`;sig=`numbers:${d}:round100:${a}`;
   }else if(variant==="round1000"){
     const a=ri(lo,hi);ans=Math.round(a/1000)*1000;text=`Округли число <b>${a}</b> до тысяч.`;vals=[ans+1000,Math.max(0,ans-1000),Math.round(a/100)*100];ex=`Смотрим на сотни. Получаем ${ans}.`;sig=`numbers:${d}:round1000:${a}`;
   }else if(variant==="round10000"){
     const a=ri(lo,hi);ans=Math.round(a/10000)*10000;text=`Округли число <b>${a}</b> до десятков тысяч.`;vals=[ans+10000,Math.max(0,ans-10000),Math.round(a/1000)*1000];ex=`Смотрим на разряд тысяч. Получаем ${ans}.`;sig=`numbers:${d}:round10000:${a}`;
   }else if(variant==="expanded"){
     const a=ri(lo,hi),s=String(a),parts=[];
     [...s].forEach((ch,i)=>{if(ch!=="0")parts.push(Number(ch)*10**(s.length-i-1))});
     text=`Какое число записано суммой <b>${parts.join(" + ")}</b>?`;ans=a;vals=[a+100,Math.max(0,a-100),a+10];ex=`Собираем число по разрядам: ${a}.`;sig=`numbers:${d}:expanded:${a}`;
   }else if(variant==="difference"){
     const a=ri(lo,hi),diff=ri(20,d===1?1000:9000),b=a+diff;text=`На сколько число <b>${b}</b> больше числа <b>${a}</b>?`;ans=diff;vals=[b,a,b+a];ex=`${b} − ${a} = ${diff}.`;sig=`numbers:${d}:difference:${a}:${b}`;
   }else{
     const a=ri(lo,hi),s=String(a),pow=ri(0,Math.min(3,s.length-1)),digit=Number(s[s.length-1-pow]),names=["единиц","десятков","сотен","тысяч"];
     text=`Какая цифра стоит в разряде <b>${names[pow]}</b> числа <b>${a}</b>?`;ans=digit;vals=[Number(s[0]),Number(s[s.length-1]),(digit+1)%10];ex=`В нужном разряде стоит цифра ${digit}.`;sig=`numbers:${d}:place:${a}:${pow}`;
   }
 }
 else if(id==="order"){
   const variants=d===0?["plusMul","mulMinus","parenSimple"]:d===1?["parenMul","exactDiv","mulPlusDiv","parenMinus"]:["parenMulMinus","doubleParen","exactDivChain","mixed"];
   variant=variants[ri(0,variants.length-1)];
   const a=ri(4,25),b=ri(2,9),c=ri(2,8),e=ri(2,12);
   if(variant==="plusMul"){ans=a+b*c;text=`${a} + ${b} × ${c} = ?`;ex=`Сначала ${b} × ${c}, затем + ${a}.`;}
   else if(variant==="mulMinus"){ans=a*c-b;text=`${a} × ${c} − ${b} = ?`;ex=`Сначала умножение, затем вычитание.`;}
   else if(variant==="parenSimple"){ans=a+(b-c);text=`${a} + (${b} − ${c}) = ?`;if(b<c){return makeQ(id)}ex=`Сначала скобки.`;}
   else if(variant==="parenMul"){ans=(a+b)*c;text=`(${a} + ${b}) × ${c} = ?`;ex=`Сначала действие в скобках.`;}
   else if(variant==="exactDiv"){const q=ri(3,20),div=ri(2,9),prod=q*div;ans=q+a;text=`${prod} : ${div} + ${a} = ?`;ex=`Сначала деление: ${prod}:${div}=${q}.`;}
   else if(variant==="mulPlusDiv"){const q=ri(2,12),div=ri(2,8),prod=q*div;ans=a*b+q;text=`${a} × ${b} + ${prod} : ${div} = ?`;ex=`Умножение и деление выполняем раньше сложения.`;}
   else if(variant==="parenMinus"){const x=Math.max(a,b+1);ans=(x-b)*c;text=`(${x} − ${b}) × ${c} = ?`;ex=`Сначала вычитание в скобках.`;}
   else if(variant==="parenMulMinus"){ans=(a+b)*c-e;text=`(${a} + ${b}) × ${c} − ${e} = ?`;ex=`Скобки → умножение → вычитание.`;}
   else if(variant==="doubleParen"){const x=Math.max(a,b+1);ans=(x-b)*(c+e);text=`(${x} − ${b}) × (${c} + ${e}) = ?`;ex=`Сначала обе скобки, затем умножение.`;}
   else if(variant==="exactDivChain"){const q=ri(3,16),div=ri(2,8),prod=q*div;ans=(a+b)+q;text=`(${a} + ${b}) + ${prod} : ${div} = ?`;ex=`Сначала скобки и деление, затем сложение.`;}
   else{ans=a*b+c*e;text=`${a} × ${b} + ${c} × ${e} = ?`;ex=`Сначала оба умножения, затем сложение.`;}
   vals=[ans+1,Math.max(0,ans-1),a+b+c];sig=`order:${d}:${variant}:${text.replace(/<[^>]+>/g,"")}`;
 }
 else if(id==="equations"){
   const variants=d===0?["plus","minus","minuend"]:d===1?["mul","div","divisor"]:["mulPlus","parenMul","divPlus"];
   variant=variants[ri(0,variants.length-1)];
   const x=ri(4,d===0?40:90),a=ri(2,d===0?20:35);
   if(variant==="plus"){const s=x+a;text=`x + ${a} = ${s}. Чему равен x?`;ans=x;ex=`x = ${s} − ${a} = ${x}.`;}
   else if(variant==="minus"){const s=x-a;if(s<0)return makeQ(id);text=`x − ${a} = ${s}. Чему равен x?`;ans=x;ex=`x = ${s} + ${a} = ${x}.`;}
   else if(variant==="minuend"){const s=x+a;text=`${s} − x = ${a}. Чему равен x?`;ans=x;ex=`x = ${s} − ${a} = ${x}.`;}
   else if(variant==="mul"){const s=x*a;text=`${a} · x = ${s}. Чему равен x?`;ans=x;ex=`x = ${s} : ${a} = ${x}.`;}
   else if(variant==="div"){const s=x*a;text=`x : ${a} = ${x}. Чему равно делимое x?`;ans=s;ex=`x = ${x} · ${a} = ${s}.`;}
   else if(variant==="divisor"){const dividend=x*a;text=`${dividend} : x = ${a}. Чему равен x?`;ans=x;ex=`x = ${dividend} : ${a} = ${x}.`;}
   else if(variant==="mulPlus"){const s=a*x+a;text=`${a} · x + ${a} = ${s}. Чему равен x?`;ans=x;ex=`Сначала вычитаем ${a}, затем делим на ${a}.`;}
   else if(variant==="parenMul"){const b=ri(2,12),s=(x+b)*a;text=`(x + ${b}) · ${a} = ${s}. Чему равен x?`;ans=x;ex=`${s}:${a}=${x+b}, затем ${x+b}−${b}=${x}.`;}
   else{const div=ri(2,8),base=x*div,b=ri(2,10),s=x+b;text=`x : ${div} + ${b} = ${s}. Чему равно x?`;ans=base;ex=`${s}−${b}=${x}, затем ${x}·${div}=${base}.`;}
   vals=[Number(ans)+a,Math.max(0,Number(ans)-a),Number(ans)+1];sig=`equations:${d}:${variant}:${text}`;
 }
 else if(id==="quantities"){
   const variants=d===0?["mcm","kgg","hmin","kmm"]:d===1?["mixedTime","mixedLength","tkg","dayh"]:["mixedKm","mixedMass","area","longTime"];
   variant=variants[ri(0,variants.length-1)];
   if(variant==="mcm"){const m=ri(2,25);ans=m*100;text=`${m} м = ? см`;ex=`${m} × 100 = ${ans} см.`;}
   else if(variant==="kgg"){const kg=ri(2,20);ans=kg*1000;text=`${kg} кг = ? г`;ex=`${kg} × 1000 = ${ans} г.`;}
   else if(variant==="hmin"){const h=ri(1,8);ans=h*60;text=`${h} ч = ? мин`;ex=`${h} × 60 = ${ans} мин.`;}
   else if(variant==="kmm"){const km=ri(1,15);ans=km*1000;text=`${km} км = ? м`;ex=`${km} × 1000 = ${ans} м.`;}
   else if(variant==="mixedTime"){const h=ri(1,5),mn=ri(5,55);ans=h*60+mn;text=`${h} ч ${mn} мин = ? мин`;ex=`${h}×60+${mn}=${ans} мин.`;}
   else if(variant==="mixedLength"){const m=ri(1,20),cm=ri(1,99);ans=m*100+cm;text=`${m} м ${cm} см = ? см`;ex=`${m}×100+${cm}=${ans} см.`;}
   else if(variant==="tkg"){const t=ri(1,9),kg=ri(10,900);ans=t*1000+kg;text=`${t} т ${kg} кг = ? кг`;ex=`${t}×1000+${kg}=${ans} кг.`;}
   else if(variant==="dayh"){const days=ri(2,7);ans=days*24;text=`${days} суток = ? ч`;ex=`${days}×24=${ans} ч.`;}
   else if(variant==="mixedKm"){const km=ri(2,15),m=ri(10,900);ans=km*1000+m;text=`${km} км ${m} м = ? м`;ex=`${km}×1000+${m}=${ans} м.`;}
   else if(variant==="mixedMass"){const kg=ri(2,30),g=ri(10,990);ans=kg*1000+g;text=`${kg} кг ${g} г = ? г`;ex=`${kg}×1000+${g}=${ans} г.`;}
   else if(variant==="area"){const m2=ri(2,20);ans=m2*100;text=`${m2} м² = ? дм²`;ex=`1 м² = 100 дм², значит ${ans} дм².`;}
   else{const dday=ri(1,4),h=ri(1,23);ans=dday*24+h;text=`${dday} сут ${h} ч = ? ч`;ex=`${dday}×24+${h}=${ans} ч.`;}
   vals=[Number(ans)+10,Math.max(0,Number(ans)-10),Math.max(1,Math.round(Number(ans)/10))];sig=`quantities:${d}:${variant}:${text}`;
 }
 else if(id==="geometry"){
   const variants=d===0?["rectArea","rectPerim","squarePerim"]:d===1?["sideByArea","sideByPerim","squareArea"]:["sideByArea","sideByPerim","squareByPerim","twoRects"];
   variant=variants[ri(0,variants.length-1)];
   if(variant==="rectArea"){const a=ri(3,18),b=ri(2,14);ans=a*b;text=`Прямоугольник: a = ${a} см, b = ${b} см. Найди площадь S.`;ex=`S = a · b = ${a}·${b} = ${ans} см².`;}
   else if(variant==="rectPerim"){const a=ri(3,18),b=ri(2,14);ans=2*(a+b);text=`Прямоугольник: a = ${a} см, b = ${b} см. Найди периметр P.`;ex=`P = 2(a+b) = ${ans} см.`;}
   else if(variant==="squarePerim"){const a=ri(3,20);ans=4*a;text=`Сторона квадрата ${a} см. Найди его периметр.`;ex=`P = 4a = ${ans} см.`;}
   else if(variant==="sideByArea"){const a=ri(3,15),b=ri(2,14),S=a*b;ans=b;text=`Площадь прямоугольника ${S} см², одна сторона ${a} см. Найди другую сторону.`;ex=`b = S : a = ${S}:${a} = ${b} см.`;}
   else if(variant==="sideByPerim"){const a=ri(3,15),b=ri(2,14),P=2*(a+b);ans=b;text=`Периметр прямоугольника ${P} см, одна сторона ${a} см. Найди другую сторону.`;ex=`a+b = ${P}:2=${a+b}; b=${a+b}−${a}=${b} см.`;}
   else if(variant==="squareArea"){const a=ri(3,16);ans=a*a;text=`Сторона квадрата ${a} см. Найди его площадь.`;ex=`S = a·a = ${ans} см².`;}
   else if(variant==="squareByPerim"){const a=ri(3,20),P=4*a;ans=a*a;text=`Периметр квадрата ${P} см. Найди его площадь.`;ex=`Сторона ${P}:4=${a} см; S=${a}·${a}=${ans} см².`;}
   else{const a=ri(3,12),b=ri(2,10),c=ri(2,8);ans=a*b+a*c;text=`Два прямоугольника имеют общую сторону ${a} см. Их другие стороны ${b} см и ${c} см. Найди сумму площадей.`;ex=`${a}·${b} + ${a}·${c} = ${ans} см².`;}
   vals=[Number(ans)+a_or_fallback(text),Math.max(0,Number(ans)-2),2*Number(ans)];sig=`geometry:${d}:${variant}:${text}`;
 }
 else{
   const variants=d===0?["cost","remainder","groups","distance","pages"]:d===1?["change","twoGoods","distance","productivity","mass"]:["meeting","twoGoodsChange","production","route","boxes"];
   variant=variants[ri(0,variants.length-1)];
   if(variant==="cost"){const price=ri(3,12)*10,count=ri(2,8);ans=price*count;text=`Купили ${count} ${ruCount(count,"тетрадь","тетради","тетрадей")} по ${price} ₽. Сколько рублей заплатили?`;ex=`${price}·${count}=${ans} ₽.`;}
   else if(variant==="remainder"){const total=ri(30,120),used=ri(5,total-10);ans=total-used;text=`Было ${total} ${ruCount(total,"карандаш","карандаша","карандашей")}. ${used} раздали. Сколько осталось?`;ex=`${total}−${used}=${ans}.`;}
   else if(variant==="groups"){const boxes=ri(3,9),each=ri(4,12);ans=boxes*each;text=`В ${boxes} коробках по ${each} ${ruCount(each,"фломастер","фломастера","фломастеров")}. Сколько фломастеров всего?`;ex=`${boxes}·${each}=${ans}.`;}
   else if(variant==="distance"){const v=ri(4,12)*5,t=ri(2,6);ans=v*t;text=`Машина ехала ${t} ч со скоростью ${v} км/ч. Какой путь она проехала?`;ex=`S=v·t=${v}·${t}=${ans} км.`;}
   else if(variant==="pages"){const per=ri(8,25),days=ri(2,6);ans=per*days;text=`За один день ученик читал ${per} ${ruCount(per,"страницу","страницы","страниц")}. Так он читал ${days} ${ruCount(days,"день","дня","дней")}. Сколько страниц он прочитал?`;ex=`${per}·${days}=${ans}.`;}
   else if(variant==="change"){const price=ri(3,12)*10,count=ri(2,8),cost=price*count,paid=(Math.ceil(cost/100)+2)*100;ans=paid-cost;text=`Купили ${count} ${ruCount(count,"тетрадь","тетради","тетрадей")} по ${price} ₽ и дали ${paid} ₽. Сколько сдачи?`;ex=`Стоимость ${cost} ₽; ${paid}−${cost}=${ans} ₽.`;}
   else if(variant==="twoGoods"){const p1=ri(2,8)*10,q1=ri(2,6),p2=ri(2,9)*10,q2=ri(2,5);ans=p1*q1+p2*q2;text=`Купили ${q1} ${ruCount(q1,"ручку","ручки","ручек")} по ${p1} ₽ и ${q2} ${ruCount(q2,"альбом","альбома","альбомов")} по ${p2} ₽. Сколько заплатили всего?`;ex=`${p1}·${q1}+${p2}·${q2}=${ans} ₽.`;}
   else if(variant==="productivity"){const per=ri(12,35),days=ri(3,7);ans=per*days;text=`Мастер за день делает ${per} ${ruCount(per,"деталь","детали","деталей")}. Сколько деталей он сделает за ${days} ${ruCount(days,"день","дня","дней")}?`;ex=`${per}·${days}=${ans}.`;}
   else if(variant==="mass"){const boxes=ri(3,8),kg=ri(4,15),sold=ri(5,boxes*kg-5);ans=boxes*kg-sold;text=`Привезли ${boxes} ${ruCount(boxes,"ящик","ящика","ящиков")} по ${kg} кг фруктов. Продали ${sold} кг. Сколько килограммов осталось?`;ex=`${boxes}·${kg}−${sold}=${ans} кг.`;}
   else if(variant==="meeting"){const v1=ri(4,9)*5,v2=ri(4,9)*5,t=ri(2,5);ans=(v1+v2)*t;text=`Два автомобиля едут навстречу друг другу со скоростями ${v1} км/ч и ${v2} км/ч. На сколько километров они сблизятся за ${t} ч?`;ex=`(${v1}+${v2})·${t}=${ans} км.`;}
   else if(variant==="twoGoodsChange"){const p1=ri(2,8)*10,q1=ri(2,5),p2=ri(2,8)*10,q2=ri(2,5),cost=p1*q1+p2*q2,paid=(Math.ceil(cost/500)+1)*500;ans=paid-cost;text=`Купили ${q1} ${ruCount(q1,"товар","товара","товаров")} по ${p1} ₽ и ${q2} ${ruCount(q2,"товар","товара","товаров")} по ${p2} ₽. Заплатили ${paid} ₽. Сколько сдачи?`;ex=`Стоимость ${cost} ₽; сдача ${paid}−${cost}=${ans} ₽.`;}
   else if(variant==="production"){const p1=ri(20,50),p2=ri(20,50),days=ri(2,5);ans=(p1+p2)*days;text=`Первая бригада за день делает ${p1} ${ruCount(p1,"деталь","детали","деталей")}, вторая — ${p2} ${ruCount(p2,"деталь","детали","деталей")}. Сколько деталей они сделают вместе за ${days} ${ruCount(days,"день","дня","дней")}?`;ex=`(${p1}+${p2})·${days}=${ans}.`;}
   else if(variant==="route"){const total=ri(300,800),first=ri(80,200),second=ri(80,Math.min(250,total-first-20));ans=total-first-second;text=`Маршрут ${total} км. В первый день проехали ${first} км, во второй ${second} км. Сколько осталось?`;ex=`${total}−${first}−${second}=${ans} км.`;}
